2	import type { FighterStats } from '../mocks/fightMock';
3	
4	function emptyStats(): FighterStats {
5	  return { sig: [0, 0], total: [0, 0], head: 0, body: 0, leg: 0, distance: 0, clinch: 0, ground: 0, td: [0, 0], ctrl: 0, kd: 0, sub: 0, acc: 0 };
6	}
