8	export function deriveLiveStats(
9	  events: Event[],
10	  currentFrame: number,
11	  fps: number,
12	): { red: FighterStats; blue: FighterStats } {
13	  const red = emptyStats();
14	  const blue = emptyStats();
15	
16	  // Track GROUND state intervals to compute control time per fighter.
17	  // initiator = the fighter who took down the opponent (they control).
18	  let groundStart: number | null = null;
19	  let groundInitiator: 'red' | 'blue' | null = null;
20	
21	  const filtered = events.filter(e => e.frame <= currentFrame);
22	
23	  for (const e of filtered) {
24	    const desc = e.description;
25	
26	    // ── Round boundaries: skip ──────────────────────────────────────
27	    if (/^Round \d+ (started|ended)$/i.test(desc)) continue;
28	
29	    // ── Fight state changes ─────────────────────────────────────────
30	    if (/^Fight state changed to/i.test(desc)) {
31	      const isGround = /FightState\.GROUND/i.test(desc);
32	
33	      if (isGround && groundStart === null) {
34	        groundStart = e.frame;
35	        const m = desc.match(/takedown initiated by (fighter_red|fighter_blue)/i);
36	        groundInitiator = m ? (m[1].toLowerCase().includes('red') ? 'red' : 'blue') : null;
37	      } else if (!isGround && groundStart !== null) {
38	        // State leaving GROUND — credit ctrl time to the initiator
39	        const seconds = (e.frame - groundStart) / fps;
40	        if (groundInitiator === 'red') red.ctrl += seconds;
41	        else if (groundInitiator === 'blue') blue.ctrl += seconds;
42	        groundStart = null;
43	        groundInitiator = null;
44	
45	        // Takedown credit: already counted when we detected the takedown event below
46	      }
47	
48	      // Count takedown attempts/landed from state transition descriptions
49	      const tdM = desc.match(/takedown initiated by (fighter_red|fighter_blue)/i);
50	      if (tdM) {
51	        const initiator = tdM[1].toLowerCase().includes('red') ? red : blue;
52	        initiator.td[0] += 1; // landed (state changed = takedown succeeded)
53	        initiator.td[1] += 1; // attempted
54	      }
55	      continue;
56	    }
57	
58	    // ── Strike events ───────────────────────────────────────────────
59	    // Pattern: "fighter_red threw a jab_head (landed)"
60	    //          "fighter_blue threw a clinch_punch"
61	    const strikeM = desc.match(/^(fighter_red|fighter_blue) threw a (\S+?)(?:\s+\((landed|missed|unconfirmed)\))?$/i);
62	    if (!strikeM) continue;
63	
64	    const isRed = strikeM[1].toLowerCase() === 'fighter_red';
65	    const st = isRed ? red : blue;
66	    const strikeType = strikeM[2].toLowerCase(); // e.g. "jab_head", "clinch_punch", "low_kick"
67	    const outcome = strikeM[3]?.toLowerCase() ?? null; // "landed" | "missed" | "unconfirmed" | null (clinch/ground)
68	
69	    // Open-range strikes have an outcome suffix; clinch/ground strikes don't
70	    const isOpenRange = outcome !== null;
71	    const isClinch = strikeType.startsWith('clinch_');
72	    const isGround = strikeType.startsWith('ground_');
73	
74	    // Attempted = every throw
75	    st.sig[1] += 1;
76	    st.total[1] += 1;
77	
78	    // Landed = open-range explicit landed, or clinch/ground (always counted as landed)
79	    const landed = outcome === 'landed' || isClinch || isGround;
80	    if (landed) {
81	      st.sig[0] += 1;
82	      st.total[0] += 1;
83	    }
84	
85	    // Position breakdown (only for landed)
86	    if (landed) {
87	      if (isClinch) st.clinch += 1;
88	      else if (isGround) st.ground += 1;
89	      else st.distance += 1;
90	    }
91	
92	    // Target breakdown (only for landed open-range strikes)
93	    if (landed && isOpenRange) {
94	      if (strikeType.endsWith('_head') || strikeType === 'head_kick') st.head += 1;
95	      else if (strikeType.endsWith('_body') || strikeType === 'middle_kick') st.body += 1;
96	      else if (strikeType === 'low_kick') st.leg += 1;
97	    }
98	  }
99	
100	  // If still in GROUND state at currentFrame, credit elapsed ctrl up to now
101	  if (groundStart !== null && groundInitiator !== null) {
102	    const seconds = (currentFrame - groundStart) / fps;
103	    if (groundInitiator === 'red') red.ctrl += seconds;
104	    else blue.ctrl += seconds;
105	  }
106	
107	  // Accuracy
108	  red.acc  = red.sig[1]  > 0 ? Math.round((red.sig[0]  / red.sig[1])  * 100) : 0;
109	  blue.acc = blue.sig[1] > 0 ? Math.round((blue.sig[0] / blue.sig[1]) * 100) : 0;
110	
111	  // ctrl: round to nearest second
112	  red.ctrl  = Math.round(red.ctrl);
113	  blue.ctrl = Math.round(blue.ctrl);
114	
115	  return { red, blue };
116	}
