16	// Aggregates events with startFrame <= e.frame <= endFrame. Used for "Whole Fight"
17	// (0..Infinity), a single round (round.start_frame..round.end_frame), and "Live"
18	// (0..currentFrame, via deriveLiveStats above).
19	export function deriveStatsForRange(
20	  events: Event[],
21	  startFrame: number,
22	  endFrame: number,
23	  fps: number,
24	): { red: FighterStats; blue: FighterStats } {
25	  const red = emptyStats();
26	  const blue = emptyStats();
27	
28	  // Track GROUND state intervals to compute control time per fighter.
29	  // initiator = the fighter who took down the opponent (they control).
30	  let groundStart: number | null = null;
31	  let groundInitiator: 'red' | 'blue' | null = null;
32	
33	  const filtered = events.filter(e => e.frame >= startFrame && e.frame <= endFrame);
34	
35	  for (const e of filtered) {
36	    const desc = e.description;
37	
38	    // ── Round boundaries: skip ──────────────────────────────────────
39	    if (/^Round \d+ (started|ended)$/i.test(desc)) continue;
40	
41	    // ── Fight state changes ─────────────────────────────────────────
42	    if (/^Fight state changed to/i.test(desc)) {
43	      const isGround = /FightState\.GROUND/i.test(desc);
44	
45	      if (isGround && groundStart === null) {
46	        groundStart = e.frame;
47	        const m = desc.match(/takedown initiated by (fighter_red|fighter_blue)/i);
48	        groundInitiator = m ? (m[1].toLowerCase().includes('red') ? 'red' : 'blue') : null;
49	      } else if (!isGround && groundStart !== null) {
50	        // State leaving GROUND — credit ctrl time to the initiator
51	        const seconds = (e.frame - groundStart) / fps;
52	        if (groundInitiator === 'red') red.ctrl += seconds;
53	        else if (groundInitiator === 'blue') blue.ctrl += seconds;
54	        groundStart = null;
55	        groundInitiator = null;
56	
57	        // Takedown credit: already counted when we detected the takedown event below
58	      }
59	
60	      // Count takedown attempts/landed from state transition descriptions
61	      const tdM = desc.match(/takedown initiated by (fighter_red|fighter_blue)/i);
62	      if (tdM) {
63	        const initiator = tdM[1].toLowerCase().includes('red') ? red : blue;
64	        initiator.td[0] += 1; // landed (state changed = takedown succeeded)
65	        initiator.td[1] += 1; // attempted
66	      }
67	      continue;
68	    }
69	
70	    // ── Strike events ───────────────────────────────────────────────
71	    // Pattern: "fighter_red threw a jab_head (landed)"
72	    //          "fighter_blue threw a clinch_punch"
73	    const strikeM = desc.match(/^(fighter_red|fighter_blue) threw a (\S+?)(?:\s+\((landed|missed|unconfirmed)\))?$/i);
74	    if (!strikeM) continue;
75	
76	    const isRed = strikeM[1].toLowerCase() === 'fighter_red';
77	    const st = isRed ? red : blue;
78	    const strikeType = strikeM[2].toLowerCase(); // e.g. "jab_head", "clinch_punch", "low_kick"
79	    const outcome = strikeM[3]?.toLowerCase() ?? null; // "landed" | "missed" | "unconfirmed" | null (clinch/ground)
80	
81	    // Open-range strikes have an outcome suffix; clinch/ground strikes don't
82	    const isOpenRange = outcome !== null;
83	    const isClinch = strikeType.startsWith('clinch_');
84	    const isGround = strikeType.startsWith('ground_');
85	
86	    // Attempted = every throw
87	    st.sig[1] += 1;
88	    st.total[1] += 1;
89	
90	    // Landed = open-range explicit landed, or clinch/ground (always counted as landed)
91	    const landed = outcome === 'landed' || isClinch || isGround;
92	    if (landed) {
93	      st.sig[0] += 1;
94	      st.total[0] += 1;
95	    }
96	
97	    // Position breakdown (only for landed)
98	    if (landed) {
99	      if (isClinch) st.clinch += 1;
100	      else if (isGround) st.ground += 1;
101	      else st.distance += 1;
102	    }
103	
104	    // Target breakdown (only for landed open-range strikes)
105	    if (landed && isOpenRange) {
106	      if (strikeType.endsWith('_head') || strikeType === 'head_kick') st.head += 1;
107	      else if (strikeType.endsWith('_body') || strikeType === 'middle_kick') st.body += 1;
108	      else if (strikeType === 'low_kick') st.leg += 1;
109	    }
110	  }
111	
112	  // If still in GROUND state at endFrame, credit elapsed ctrl up to there.
113	  // endFrame may be Infinity (whole-fight scope) — cap at the last real event
114	  // frame so an unclosed ground state doesn't produce infinite control time.
115	  if (groundStart !== null && groundInitiator !== null) {
116	    const cap = Number.isFinite(endFrame) ? endFrame : filtered[filtered.length - 1]?.frame ?? groundStart;
117	    const seconds = (cap - groundStart) / fps;
118	    if (groundInitiator === 'red') red.ctrl += seconds;
119	    else blue.ctrl += seconds;
120	  }
121	
122	  // Accuracy
123	  red.acc  = red.sig[1]  > 0 ? Math.round((red.sig[0]  / red.sig[1])  * 100) : 0;
124	  blue.acc = blue.sig[1] > 0 ? Math.round((blue.sig[0] / blue.sig[1]) * 100) : 0;
125	
126	  // ctrl: round to nearest second
127	  red.ctrl  = Math.round(red.ctrl);
128	  blue.ctrl = Math.round(blue.ctrl);
129	
130	  return { red, blue };
131	}
